F='D:/the-synaptic-sea-2d/design/gdd/save-load-and-versioned-format.md'
def load():
    return open(F,encoding='utf-8',newline='').read()
def save(s):
    open(F,'w',encoding='utf-8',newline='').write(s)
class Ed:
    def __init__(self):
        self.s=load(); self.log=[]; self.fail=0
    def rep(self,old,new,count=1,tag=''):
        n=self.s.count(old)
        if n!=count:
            print(f"FAIL[{tag}] expected {count} got {n}: {old[:90]!r}"); self.fail+=1; return
        self.s=self.s.replace(old,new); self.log.append((tag,count))
    def done(self):
        if self.fail: print("NOT SAVED, failures:",self.fail); sys.exit(1)
        save(self.s); print("saved",len(self.log),"edits")
EOF
